/** Authenticated managed shares. A share never supplies JWT authority or widens scope. */
import { ConvexError, v } from "convex/values";
import { mutation, query, internalMutation } from "./_generated/server";
import { internalUnavailable } from "./runtimeUnavailableAuth";
import { bindDataActor, dataAuthorityReference, managedConversationAccess, requireDataAuthority } from "./runtimeDataAuth";
import { checkConversation, conversationById, requireConversation, singleTranscript, transcriptDenied } from "./runtimeTranscript";
import { boundedIdentifier } from "./_cortex/shared/domain/transcript";

async function shareById(ctx: Pick<import("./_generated/server").QueryCtx, "db">, reference: import("./_cortex/shared/auth/verified").RuntimeAuthorityReference, shareId: string) {
  return singleTranscript(await ctx.db.query("runtimeConversationShares").withIndex("by_scoped_id", q => q.eq("tenantId", reference.tenantId).eq("memorySpaceId", reference.memorySpaceId!).eq("shareId", shareId)).take(2));
}
function view(row: import("./_generated/dataModel").Doc<"runtimeConversationShares">) {
  return { _id: row._id, grantedBy: row.ownerPrincipalId, sourceMemorySpaceId: row.memorySpaceId, redactSensitive: false, revokedAt: row.revokedAt, tenantId: row.tenantId, shareId: row.shareId, conversationId: row.conversationId, grantType: row.grantType, grantedTo: row.grantedTo,
    permissions: row.permissions, status: row.revokedAt !== undefined ? "revoked" : row.expiresAt !== undefined && Date.now() >= row.expiresAt ? "expired" : "active",
    expiresAt: row.expiresAt, maxViews: row.maxViews, viewCount: row.viewCount, createdAt: row.createdAt };
}

export const create = mutation({ args: {
    memorySpaceId: v.optional(v.string()),
    conversationId: v.string(),
    grantedBy: v.string(), // userId who is sharing
    sourceMemorySpaceId: v.optional(v.string()), // Deprecated: now derived from conversation
    grantType: v.union(
      v.literal("user"),
      v.literal("space"),
      v.literal("link"),
      v.literal("domain"),
    ),
    grantedTo: v.optional(v.string()),
    permissions: v.object({
      canView: v.boolean(),
      canViewFacts: v.boolean(),
      canViewMemories: v.boolean(),
      canContinue: v.boolean(),
      canFork: v.boolean(),
      canExport: v.boolean(),
    }),
    expiresAt: v.optional(v.number()),
    maxViews: v.optional(v.number()),
    redactBefore: v.optional(v.number()),
    redactSensitive: v.optional(v.boolean()),
    tenantId: v.optional(v.string()),
  }, handler: async (ctx, args) => {
  const { actor, reference, conversation } = await requireConversation(ctx, args, args.conversationId, "admin");
  bindDataActor(actor, args.grantedBy);
  if (args.sourceMemorySpaceId !== undefined && args.sourceMemorySpaceId !== conversation.memorySpaceId) transcriptDenied();
  if (args.grantType !== "user" && args.grantType !== "space") transcriptDenied("CAPABILITY_UNAVAILABLE");
  if (args.redactBefore !== undefined || args.redactSensitive) transcriptDenied("CAPABILITY_UNAVAILABLE");
  // Query delivery cannot atomically consume a view. Do not accept an unenforced limit.
  if (args.maxViews !== undefined) transcriptDenied("CAPABILITY_UNAVAILABLE");
  if (args.expiresAt !== undefined && (!Number.isSafeInteger(args.expiresAt) || args.expiresAt <= Date.now())
    || args.maxViews !== undefined && (!Number.isSafeInteger(args.maxViews) || args.maxViews < 1)) transcriptDenied("INVALID_INPUT");
  if (!args.grantedTo) transcriptDenied("INVALID_INPUT"); boundedIdentifier(args.grantedTo); let grantedTo = args.grantedTo;
  if (args.grantType === "space") { if (args.grantedTo !== conversation.memorySpaceId) transcriptDenied(); }
  else {
    const principalId = ctx.db.normalizeId("runtimeAuthPrincipals", args.grantedTo);
    const creatorId = ctx.db.normalizeId("runtimeAuthPrincipals", actor.principalId);
    const creator = creatorId ? await ctx.db.get("runtimeAuthPrincipals", creatorId) : null;
    const exact = principalId ? await ctx.db.get("runtimeAuthPrincipals", principalId) : null;
    const target = exact ? [exact] : creator ? await ctx.db.query("runtimeAuthPrincipals").withIndex("by_issuer_subject", q => q.eq("issuer", creator.issuer).eq("subject", args.grantedTo!)).take(2) : [];
    if (target.length !== 1 || target[0].deletedAt !== undefined) transcriptDenied(); grantedTo = target[0]._id;
    const memberships = await ctx.db.query("runtimeAuthMemberships").withIndex("by_principal_tenant", q => q.eq("principalId", target[0]._id).eq("tenantId", actor.tenantId)).take(2);
    if (memberships.length !== 1 || memberships[0].revokedAt !== undefined || memberships[0].deletedAt !== undefined) transcriptDenied();
  }
  const active = await ctx.db.query("runtimeConversationShares").withIndex("by_conversation_state", q => q.eq("tenantId", actor.tenantId).eq("memorySpaceId", actor.memorySpaceId).eq("conversationId", conversation.conversationId).eq("state", "active")).take(65);
  if (active.length >= 64) transcriptDenied("QUERY_TOO_BROAD");
  const shareId = `share:${crypto.randomUUID()}`;
  const id = await ctx.db.insert("runtimeConversationShares", { tenantId: actor.tenantId, memorySpaceId: actor.memorySpaceId, ownerPrincipalId: actor.principalId,
    shareId, conversationId: conversation.conversationId, grantType: args.grantType, grantedTo, permissions: args.permissions,
    state: "active", actorReference: reference, ...(args.expiresAt === undefined ? {} : { expiresAt: args.expiresAt }),
    ...(args.maxViews === undefined ? {} : { maxViews: args.maxViews }), viewCount: 0, createdAt: Date.now() });
  return view((await ctx.db.get("runtimeConversationShares", id))!);
} });

export const revoke = mutation({ args: {
    tenantId: v.optional(v.string()),
    memorySpaceId: v.optional(v.string()),
    shareId: v.string(),
    // Optional: caller's userId for authorization
    userId: v.optional(v.string()),
  }, handler: async (ctx, args) => {
  const actor = await requireDataAuthority(ctx, args, "admin"); bindDataActor(actor, args.userId); const reference = dataAuthorityReference(actor);
  const row = await shareById(ctx, reference, args.shareId); if (!row) transcriptDenied();
  const conversation = await conversationById(ctx, reference, row.conversationId); if (!conversation) transcriptDenied();
  await checkConversation(ctx, reference, conversation, "admin");
  if (row.revokedAt === undefined) await ctx.db.patch("runtimeConversationShares", row._id, { state: "revoked", revokedAt: Date.now(), revocationActor: reference });
  return view((await ctx.db.get("runtimeConversationShares", row._id))!);
} });

export const incrementViewCount = internalMutation({ args: {
    shareId: v.string(),
  }, handler: async (_ctx, _args) => {
  return await internalUnavailable();
} });

export const get = query({ args: {
    tenantId: v.optional(v.string()),
    memorySpaceId: v.optional(v.string()),
    shareId: v.string(),
  }, handler: async (ctx, args) => {
  const actor = await requireDataAuthority(ctx, args, "read"); const reference = dataAuthorityReference(actor);
  const row = await shareById(ctx, reference, args.shareId); if (!row) return null;
  const conversation = await conversationById(ctx, reference, row.conversationId); if (!conversation) transcriptDenied();
  await checkConversation(ctx, reference, conversation, "read"); return view(row);
} });

export const listByConversation = query({ args: {
    tenantId: v.optional(v.string()),
    memorySpaceId: v.optional(v.string()),
    conversationId: v.string(),
    status: v.optional(
      v.union(v.literal("active"), v.literal("revoked"), v.literal("expired")),
    ),
  }, handler: async (ctx, args) => {
  const { conversation, reference } = await requireConversation(ctx, args, args.conversationId, "admin");
  return (await ctx.db.query("runtimeConversationShares").withIndex("by_conversation", q => q.eq("tenantId", reference.tenantId).eq("memorySpaceId", reference.memorySpaceId!).eq("conversationId", conversation.conversationId)).take(100))
    .map(view).filter(row => !args.status || row.status === args.status);
} });

export const listByGranter = query({ args: {
    tenantId: v.optional(v.string()),
    memorySpaceId: v.optional(v.string()),
    grantedBy: v.string(),
    status: v.optional(
      v.union(v.literal("active"), v.literal("revoked"), v.literal("expired")),
    ),
  }, handler: async (ctx, args) => {
  const actor = await requireDataAuthority(ctx, args, "admin"); bindDataActor(actor, args.grantedBy); const reference = dataAuthorityReference(actor);
  const rows = await ctx.db.query("runtimeConversationShares").withIndex("by_owner", q => q.eq("tenantId", actor.tenantId).eq("memorySpaceId", actor.memorySpaceId).eq("ownerPrincipalId", actor.principalId)).take(100);
  const result = []; for (const row of rows) { const conversation = await conversationById(ctx, reference, row.conversationId); if (!conversation || conversation.tombstonedAt !== undefined) continue; await checkConversation(ctx, reference, conversation, "admin"); const item = view(row); if (!args.status || item.status === args.status) result.push(item); }
  return result;
} });

export const checkAccess = query({ args: {
    tenantId: v.optional(v.string()),
    conversationId: v.string(),
    userId: v.optional(v.string()),
    memorySpaceId: v.optional(v.string()),
    emailDomain: v.optional(v.string()),
  }, handler: async (ctx, args) => {
  const { actor, reference, conversation } = await requireConversation(ctx, args, args.conversationId, "read"); bindDataActor(actor, args.userId);
  if (args.emailDomain !== undefined) transcriptDenied("INVALID_INPUT");
  const permissions = { canView: true, canViewFacts: false, canViewMemories: false, canExport: false, canFork: false, canContinue: false };
  for (const permission of ["canViewFacts", "canViewMemories", "canExport", "canFork", "canContinue"] as const) {
    if ((permission === "canFork" || permission === "canContinue") && !actor.capabilities.includes("write")) continue;
    try { await managedConversationAccess(ctx, reference, conversation, permission === "canContinue" ? "write" : "read", permission);
      permissions[permission] = permission !== "canContinue" || !conversation.manualWriteLocked; }
    catch (error) { if (!(error instanceof ConvexError) || error.data.code !== "FORBIDDEN") throw error; }
  }
  return { hasAccess: true as const, permissions, share: null, reason: "CURRENT_AUTHORITY" };
} });

/** A belief plan, read versions, ordered slot heads, history and outbox commit together. */
import { v } from "convex/values";
import { internalMutation } from "./_generated/server";
import type { MutationCtx } from "./_generated/server";
import type { AttributedFact } from "./_cortex/shared/domain/contracts";
import { canonicalModelJson } from "./_cortex/shared/domain/model_policy";
import { semanticHash } from "./_cortex/shared/domain/profile";
import { planBeliefs } from "./_cortex/shared/domain/belief_plan";
import type { BeliefPlanV1 } from "./_cortex/shared/domain/belief_plan";
import { BELIEF_POLICY_VERSION } from "./_cortex/shared/domain/ingestion";
import { runtimeAuthorityReference } from "./runtimeAuthSchema";
import { ingestionStage } from "./runtimeIngestionSchema";
import { ConvexMemoryRepository } from "./runtimeMemoryRepository";
import { finishBeliefStage, requireStageCommit, ingestionDenied } from "./runtimeIngestion";
import type { StageLease } from "./runtimeIngestion";
import { enqueueSourceProjection } from "./runtimeGraph";

export async function commitBeliefPlan(ctx: MutationCtx, args: StageLease & { planCanonical: string }) {
  const current = await requireStageCommit(ctx, args);
  if (args.stage !== "facts" || current.source.lineage.role === "assistant" || new TextEncoder().encode(args.planCanonical).length > 1_000_000) ingestionDenied("INVALID_INPUT");
  const plan = JSON.parse(args.planCanonical) as BeliefPlanV1;
  if (canonicalModelJson(plan) !== args.planCanonical || plan.version !== 1 || plan.eventId !== current.event.eventId
    || plan.sequence !== current.event.sequence || plan.sourceHash !== current.source.contentHash) ingestionDenied("INVALID_BELIEF_PLAN");
  const extraction = await ctx.db.query("runtimeIngestionStages").withIndex("by_event_stage", q => q.eq("tenantId", current.event.tenantId)
    .eq("memorySpaceId", current.event.memorySpaceId).eq("eventId", current.event.eventId).eq("stage", "extract")).unique();
  if (!extraction || extraction.state !== "complete" || !extraction.payloadCanonical) ingestionDenied("INVALID_STATE");
  const candidates = JSON.parse(extraction.payloadCanonical) as AttributedFact[];
  const repository = new ConvexMemoryRepository(ctx, args.reference, "write", ctx.db);
  const existing = await repository.listFacts({ limit: 100 }); if (existing.length === 100) ingestionDenied("BELIEF_SCOPE_TOO_BROAD");
  // Include all consumed versions, even candidates which were not rewritten.
  for (const [factId, expected] of Object.entries(plan.expectedVersions ?? {})) {
    const fact = await ctx.db.query("facts").withIndex("by_runtime_scope_factId", q => q.eq("tenantId", current.event.tenantId).eq("memorySpaceId", current.event.memorySpaceId).eq("factId", factId)).unique();
    if (expected !== (fact?.version ?? 0)) ingestionDenied("FACT_VERSION_CONFLICT");
  }
  const checked = await planBeliefs({ eventId: current.event.eventId, sequence: current.event.sequence, source: current.source, candidates, existing,
    resolve: async (_candidate, _existing, ordinal) => { const entry = plan.entries[ordinal]; if (!entry) ingestionDenied("INVALID_BELIEF_PLAN"); return entry.decision; } });
  if (canonicalModelJson(checked) !== args.planCanonical) ingestionDenied("FACT_VERSION_CONFLICT");
  // Exact source order defeats reversed model completion, not merely source wall-clock time.
  for (const entry of plan.entries) {
    const head = await ctx.db.query("runtimeBeliefHeads").withIndex("by_slot", q => q.eq("tenantId", current.event.tenantId).eq("memorySpaceId", current.event.memorySpaceId).eq("slotKey", entry.slotKey)).unique();
    if (head && head.sequence >= current.event.sequence && head.eventId !== current.event.eventId) ingestionDenied("BELIEF_ORDER_CONFLICT");
  }
  const facts = plan.entries.flatMap(entry => entry.next ? [entry.next] : []);
  const identity = { sourceId: current.source.lineage.sourceId, sourceEventId: current.source.lineage.sourceEventId,
    sourceRevision: current.source.lineage.sourceRevision, stage: "facts" as const, semanticPolicyVersion: BELIEF_POLICY_VERSION };
  const source = { sourceId: identity.sourceId, sourceEventId: identity.sourceEventId, sourceRevision: identity.sourceRevision };
  const receipt = await repository.commitDerived({ source, identity, facts, expectedFactVersions: plan.expectedVersions });
  if (!receipt.created) ingestionDenied("INGESTION_CONFLICT");
  for (const entry of plan.entries) {
    const before = entry.targetFactId ? existing.find(f => f.factId === entry.targetFactId) : undefined;
    const factId = entry.next?.factId ?? entry.targetFactId!;
    if (entry.decision.action === "SUPERSEDE") {
      const prior = await ctx.db.query("facts").withIndex("by_runtime_scope_factId", q => q.eq("tenantId", current.event.tenantId).eq("memorySpaceId", current.event.memorySpaceId).eq("factId", entry.targetFactId!)).unique();
      if (!prior || prior.version !== plan.expectedVersions[prior.factId]) ingestionDenied("FACT_VERSION_CONFLICT");
      await ctx.db.patch("facts", prior._id, { supersededBy: factId, version: prior.version + 1, updatedAt: Date.now() });
    }
    const head = await ctx.db.query("runtimeBeliefHeads").withIndex("by_slot", q => q.eq("tenantId", current.event.tenantId).eq("memorySpaceId", current.event.memorySpaceId).eq("slotKey", entry.slotKey)).unique();
    const headValue = { tenantId: current.event.tenantId, memorySpaceId: current.event.memorySpaceId, slotKey: entry.slotKey, factId,
      sequence: current.event.sequence, eventId: current.event.eventId, version: (head?.version ?? 0) + 1, updatedAt: Date.now() };
    if (head) await ctx.db.replace("runtimeBeliefHeads", head._id, headValue); else await ctx.db.insert("runtimeBeliefHeads", headValue);
    const historyId = `belief-history:${await semanticHash(canonicalModelJson([current.event.eventId, entry.ordinal, factId]))}`;
    await ctx.db.insert("runtimeBeliefHistory", { tenantId: current.event.tenantId, memorySpaceId: current.event.memorySpaceId, historyId,
      eventId: current.event.eventId, sequence: current.event.sequence, factId, action: entry.decision.action,
      ...(before ? { beforeCanonical: canonicalModelJson(before) } : {}), ...(entry.next ? { afterCanonical: canonicalModelJson(entry.next) } : {}),
      planCanonical: args.planCanonical, actorReference: args.reference, createdAt: Date.now() });
  }
  await ctx.db.insert("runtimeBeliefOutbox", { tenantId: current.event.tenantId, memorySpaceId: current.event.memorySpaceId,
    eventId: current.event.eventId, receiptId: receipt.receiptId, sequence: current.event.sequence, factIds: facts.map(f => f.factId), state: "pending", createdAt: Date.now() });
  const affectedSources = new Set([current.source.lineage.sourceId, ...plan.entries.flatMap(entry => {
    const old = entry.targetFactId ? existing.find(f => f.factId === entry.targetFactId) : undefined;
    return old ? [old.lineage.sourceId] : [];
  })]);
  for (const sourceId of affectedSources) await enqueueSourceProjection(ctx, args.reference, sourceId);
  await finishBeliefStage(ctx, args, receipt.receiptId, args.planCanonical);
  return receipt;
}
export const commit = internalMutation({ args: { reference: runtimeAuthorityReference, eventId: v.string(), stage: ingestionStage,
  attempt: v.number(), leaseVersion: v.number(), planCanonical: v.string() }, handler: async (ctx, args) => await commitBeliefPlan(ctx, args) });

/** Durable external graph intent, trusted worker leases and current-authorized reads. */
import { ConvexError, v } from "convex/values";
import { makeFunctionReference } from "convex/server";
import { internalMutation, mutation, query } from "./_generated/server";
import type { MutationCtx, QueryCtx } from "./_generated/server";
import type { Doc } from "./_generated/dataModel";
import type { RuntimeAuthorityReference } from "./_cortex/shared/auth/verified";
import type { EmbeddingProfile } from "./_cortex/shared/domain/profile";
import type { GraphProjectionLeaseV1, GraphProjectionPayloadV1, GraphProjectionWorkV1, GraphExpansionWorkV1 } from "./_cortex/shared/domain/graph_projection";
import { GRAPH_PROJECTION_LIMITS } from "./_cortex/shared/domain/graph_projection";
import { DEFAULT_EMBEDDING_PROFILE, SUPPORTED_EMBEDDING_PROFILES, assertSupportedEmbeddingProfile, semanticHash } from "./_cortex/shared/domain/profile";
import { canonicalModelJson } from "./_cortex/shared/domain/model_policy";
import { contiguousWatermark } from "./_cortex/shared/domain/memory_context";
import { runtimeAuthorityReference } from "./runtimeAuthSchema";
import { graphLease, graphReceipt } from "./runtimeGraphSchema";
import { embeddingProfile } from "./runtimeMemorySchema";
import { createAuthorityReader, recheckAuthority } from "./runtimeAuth";
import { dataAuthorityReference, dataDenied, requireDataAuthority, managedSourceIsCurrent, getScopedFact } from "./runtimeDataAuth";
type ReadCtx = Pick<QueryCtx, "db" | "runQuery">;
type ProjectionCtx = Pick<MutationCtx, "db"> & Partial<Pick<MutationCtx, "scheduler" | "runQuery">>;
type Scope = { tenantId: string; memorySpaceId: string };
type Source = Doc<"runtimeGraphSources">;
type Job = Doc<"runtimeGraphOutbox">;
const selectors = { tenantId: v.string(), memorySpaceId: v.string() };
const refreshRef = makeFunctionReference<"mutation", { reference: RuntimeAuthorityReference }>("runtimeMemoryContext:refreshWatermarks");
async function selectedProfile(ctx: Pick<QueryCtx, "runQuery">, reference: RuntimeAuthorityReference, operationKey: "embedding.memory" | "embedding.query" = "embedding.memory"): Promise<EmbeddingProfile> {
  return ctx.runQuery(makeFunctionReference<"query", { reference: RuntimeAuthorityReference; operationKey: "embedding.memory" | "embedding.query" }, EmbeddingProfile>("runtimeModelPolicy:embeddingProfile"), { reference, operationKey });
}
async function currentSource(ctx: ReadCtx, reference: RuntimeAuthorityReference, sourceId: string, capability: "read" | "write") {
  const s = scope(reference); const source = await sourceRow(ctx, s, sourceId);
  await recheckAuthority(ctx, reference, { ...s, capability, ...(source ? { resource: { ...s, resourceType: "source" as const, resourceId: sourceId, ownerPrincipalId: source.ownerPrincipalId } } : {}) });
  if (!source || !await managedSourceIsCurrent(ctx, reference, source, capability, "canViewFacts")) dataDenied("STALE_SOURCE");
  return source;
}
function knownCurrentnessDenial(error: unknown) {
  if (!(error instanceof ConvexError)) return false;
  const data = error.data;
  return data !== null && typeof data === "object" && "code" in data && ["FORBIDDEN", "STALE_SOURCE", "PROFILE_NOT_READY", "POLICY_DENIED"].includes(String(data.code));
}
function positive(value: number) { if (!Number.isSafeInteger(value) || value < 1) dataDenied("INVALID_INPUT"); }
function scope(reference: RuntimeAuthorityReference): Scope {
  if (!reference.memorySpaceId || !reference.memorySpaceEpoch) dataDenied();
  return { tenantId: reference.tenantId, memorySpaceId: reference.memorySpaceId };
}
async function sourceRow(ctx: Pick<QueryCtx, "db">, s: Scope, sourceId: string) {
  return ctx.db.query("runtimeMemorySources").withIndex("by_scope_source", q => q.eq("tenantId", s.tenantId)
    .eq("memorySpaceId", s.memorySpaceId).eq("lineage.sourceId", sourceId)).unique();
}
async function intent(ctx: Pick<QueryCtx, "db">, s: Scope, sourceId: string) {
  return ctx.db.query("runtimeGraphSources").withIndex("by_source", q => q.eq("tenantId", s.tenantId)
    .eq("memorySpaceId", s.memorySpaceId).eq("sourceId", sourceId)).unique();
}
async function connector(ctx: Pick<QueryCtx, "db">, s: Scope, connectorId: string) {
  const row = await ctx.db.query("runtimeGraphConnectors").withIndex("by_connector", q => q.eq("tenantId", s.tenantId)
    .eq("memorySpaceId", s.memorySpaceId).eq("connectorId", connectorId)).unique();
  if (!row?.enabled) dataDenied("GRAPH_UNAVAILABLE", "Graph connector is unavailable"); return row;
}
async function worker(ctx: Pick<QueryCtx, "db" | "auth">, s: Scope, connectorId: string) {
  const configured = await connector(ctx, s, connectorId);
  const actor = await requireDataAuthority(ctx, { tenantId: configured.workerTenantId, memorySpaceId: configured.workerMemorySpaceId }, "admin");
  if (actor.actorKind !== "service" || actor.resourceAccess === "own" || actor.principalId !== configured.workerPrincipalId) dataDenied();
  return configured;
}
async function payloadFor(ctx: Pick<QueryCtx, "db">, s: Scope, revision: number): Promise<GraphProjectionPayloadV1> {
  const row = await ctx.db.query("runtimeGraphPayloads").withIndex("by_revision", q => q.eq("tenantId", s.tenantId)
    .eq("memorySpaceId", s.memorySpaceId).eq("revision", revision)).unique();
  if (!row) dataDenied("GRAPH_STATE_INVALID"); return JSON.parse(row.payloadCanonical) as GraphProjectionPayloadV1;
}
async function updateEvent(ctx: ProjectionCtx, value: Source, state: "pending" | "complete" | "dead_letter") {
  const events = await ctx.db.query("runtimeIngestionEvents").withIndex("by_source", q => q.eq("tenantId", value.tenantId)
    .eq("memorySpaceId", value.memorySpaceId).eq("lineage.sourceId", value.sourceId).eq("lineage.sourceRevision", value.sourceRevision)).take(2);
  for (const event of events) if (event.lineage.sourceEventId === value.sourceEventId && event.contentHash === value.contentHash) {
    await ctx.db.patch("runtimeIngestionEvents", event._id, { graphState: state === "dead_letter" ? "failed" : state,
      graphProfilesComplete: state === "complete" ? [value.profile.profileId] : [] });
  }
  if (value.authorityReference && ctx.scheduler) await ctx.scheduler.runAfter(0, refreshRef, { reference: value.authorityReference });
}
async function enqueueJob(ctx: ProjectionCtx, value: Source, connectorId: string) {
  const jobId = `graph:${await semanticHash(canonicalModelJson([value.tenantId, value.memorySpaceId, connectorId, value.sourceId, value.revision, value.payloadHash]))}`;
  const existing = await ctx.db.query("runtimeGraphOutbox").withIndex("by_job", q => q.eq("tenantId", value.tenantId)
    .eq("memorySpaceId", value.memorySpaceId).eq("connectorId", connectorId).eq("jobId", jobId)).unique();
  if (existing) return;
  for (const state of ["pending", "running"] as const) {
    const old = await ctx.db.query("runtimeGraphOutbox").withIndex("by_queue", q => q.eq("tenantId", value.tenantId)
      .eq("memorySpaceId", value.memorySpaceId).eq("connectorId", connectorId).eq("state", state)).filter(q => q.eq(q.field("sourceId"), value.sourceId)).take(2);
    for (const row of old) await ctx.db.patch("runtimeGraphOutbox", row._id, { state: "superseded", updatedAt: Date.now() });
  }
  await ctx.db.insert("runtimeGraphOutbox", { tenantId: value.tenantId, memorySpaceId: value.memorySpaceId, connectorId, jobId,
    sourceId: value.sourceId, revision: value.revision, payloadHash: value.payloadHash, state: "pending", attempt: 0,
    leaseVersion: 0, retryAt: 0, createdAt: Date.now(), updatedAt: Date.now() });
}
/** Atomic caller supplies identities only; payload is built from current Core rows. */
export async function enqueueSourceProjection(ctx: ProjectionCtx, reference: RuntimeAuthorityReference, sourceId: string,
  selected?: EmbeddingProfile) {
  const s = scope(reference);
  const configured = await ctx.db.query("runtimeGraphConnectors").withIndex("by_scope", q => q.eq("tenantId", s.tenantId).eq("memorySpaceId", s.memorySpaceId)).take(3);
  let profile = selected;
  if (!profile && configured.some(c => c.enabled)) {
    if (!ctx.runQuery) dataDenied("GRAPH_POLICY_UNAVAILABLE");
    profile = await selectedProfile({ runQuery: ctx.runQuery }, reference);
  }
  profile ??= DEFAULT_EMBEDDING_PROFILE; assertSupportedEmbeddingProfile(profile);
  const source = await sourceRow(ctx, s, sourceId);
  if (!source) dataDenied("STALE_SOURCE");
