/** Scoped Convex adapters. Every sensitive operation reloads the persisted grant. */
import { ConvexError } from "convex/values";
import { makeFunctionReference } from "convex/server";
import type { FunctionReference } from "convex/server";
import type { ActionCtx, MutationCtx, QueryCtx } from "./_generated/server";
import type { Doc, Id } from "./_generated/dataModel";
import type { RuntimeAuthority, RuntimeAuthorityReference, RuntimeResource } from "./_cortex/shared/auth/verified";
import type { DerivedFact, DerivedVector, MemoryRepository, ProfiledQuery, SourceChunk, SourceContent, TrustedMemoryScope, VectorMatch } from "./_cortex/shared/domain/contracts";
import type { DomainClock } from "./_cortex/shared/domain/clock";
import { DEFAULT_EMBEDDING_PROFILE, LARGE_EMBEDDING_PROFILE, assertSupportedEmbeddingProfile, assertEmbeddingVector, assertProfileMatches, normalizeSourceText, semanticHash } from "./_cortex/shared/domain/profile";
import { assertSourceLineage, isCurrentAuthorizedVector, prepareSourceContent, processingIdentityKey } from "./_cortex/shared/domain/sources";
import { assertResourceScope, createAuthorityReader, recheckAuthority } from "./runtimeAuth";
import { managedSourceIsCurrent } from "./runtimeDataAuth";
import type { EmbeddingProfile } from "./_cortex/shared/domain/profile";
import type { ContextSourcePermission } from "./_cortex/shared/domain/context_witness";
